import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides } from '../game/neon.js';

test('D1 - No bounce on brick hit', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;

  // Position ball to collide with brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vy = -200; // moving up

  const initialVy = state.ball.vy;

  // Mock ctx
  const ctx = {
    fillRect: () => {},
    fillText: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  frame(ctx, state);

  assert.notStrictEqual(state.ball.vy, initialVy, 'Ball should have bounced (vy changed)');
});

test('D2 - Tunneling at high speed', () => {
  const state = createState(5); // speed is 620
  const brick = state.bricks[0];
  brick.alive = true;

  // Ball is just above the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; // Just above
  state.ball.vy = 620; // Moving down fast

  // One step with max dt (0.05s)
  // Displacement = 620 * 0.05 = 31px
  // New y = 48 - 10 + 31 = 69.
  // Brick is at y=48, h=20 -> bottom is 68.
  // The ball's center is now at 69. Ball radius is 7.
  // ball.y - ball.r = 62. This is inside the brick? 
  // No, let's make it tunnel completely.

  state.ball.y = brick.y - 10; 
  // Move it so that it's completely past the brick in one step.
  // Brick top: 48, bottom: 68.
  // If ball is at 40, and moves 40px, it's at 80.
  // Radius 7. Top is 73. It completely skipped the brick.

  const ctx = {
    fillRect: () => {},
    fillText: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  // Simulating the movement and the frame call
  const dt = 0.05;
  const speed = 1000; // Force higher speed for clear tunneling
  state.ball.vy = speed;
  state.ball.y = brick.y - 10; 

  // step() handles movement
  import { step } from '../game/neon.js';
  step(state, dt); // ball.y becomes 48-10 + 1000*0.05 = 38 + 50 = 88

  frame(ctx, state);

  assert.strictEqual(brick.alive, false, 'Brick should have been broken even if tunneled');
});

